// The easing solve and channel evaluator, mirrored from Rust (11.11).
//
// **Rust owns this specification.** `gx_contracts::animation::ease_at` is the
// authority; this is the second implementation, and it exists because the
// speed graph draws a curve at pixel resolution and a browser cannot call
// across the IPC boundary once per pixel.
//
// Two implementations of one specification is exactly the drift ADR-003 names
// as a real cost, so it is pinned the same way the colour transfer curves are
// (11.4): `easing-reference.ts` is generated by running the *Rust* functions,
// and a test asserts this file reproduces it. An easing changed on one side
// and not the other fails the gate in the same run — which matters more here
// than almost anywhere else, because the failure mode is a preview that lies
// about what will go to air.

import type { CubicBezier, SceneEasing, SceneKeyframe } from "@grapix/contracts";

import { NAMED_EASING_POINTS } from "../easing-reference";

/// Anything carrying a channel's keys.
///
/// The evaluator reads keys and nothing else, so taking this rather than a
/// full `KeyframeChannel` lets the timeline model pass its borrowed
/// `readonly` array straight through without a copy.
export type ChannelKeys = { readonly keys: readonly SceneKeyframe[] };

const LINEAR: CubicBezier = { x1: 0, y1: 0, x2: 1, y2: 1 };

/// The control points a named easing stands for, read from the generated
/// table rather than restated — the table comes from Rust, so there is no
/// second list of numbers to drift.
export function easingControlPoints(easing: SceneEasing): CubicBezier {
  const points = (NAMED_EASING_POINTS as Record<string, CubicBezier | undefined>)[easing];
  return points ?? LINEAR;
}

/// One coordinate of a cubic bezier with endpoints fixed at 0 and 1.
/// Expanded Bernstein form, identical to the Rust so the two stay comparable.
function bezierAxis(c1: number, c2: number, u: number): number {
  const inv = 1 - u;
  return 3 * inv * inv * u * c1 + 3 * inv * u * u * c2 + u * u * u;
}

function bezierAxisSlope(c1: number, c2: number, u: number): number {
  const inv = 1 - u;
  return 3 * inv * inv * c1 + 6 * inv * u * (c2 - c1) + 3 * u * u * (1 - c2);
}

/// Solve the curve for `t`, returning eased 0–1 progress.
///
/// Newton-Raphson with a bisection fallback where the slope is too flat to
/// step safely — the method browsers use for `cubic-bezier()`, and the same
/// one the Rust uses, iteration for iteration.
export function easeAt(
  easing: SceneEasing,
  bezier: CubicBezier | undefined,
  t: number,
): number {
  if (!Number.isFinite(t)) return 0;
  const clamped = Math.min(1, Math.max(0, t));
  // A hold does not interpolate: it stays on the from-key until the next one.
  if (easing === "hold") return 0;

  const points =
    easing === "custom-bezier" ? (bezier ?? LINEAR) : easingControlPoints(easing);

  if (points.x1 === 0 && points.y1 === 0 && points.x2 === 1 && points.y2 === 1) {
    return clamped;
  }
  if (clamped === 0 || clamped === 1) return clamped;

  let u = clamped;
  for (let i = 0; i < 8; i += 1) {
    const x = bezierAxis(points.x1, points.x2, u) - clamped;
    if (Math.abs(x) < 1e-9) return bezierAxis(points.y1, points.y2, u);
    const slope = bezierAxisSlope(points.x1, points.x2, u);
    if (Math.abs(slope) < 1e-9) break;
    u -= x / slope;
  }

  let low = 0;
  let high = 1;
  let mid = clamped;
  for (let i = 0; i < 64; i += 1) {
    mid = 0.5 * (low + high);
    const x = bezierAxis(points.x1, points.x2, mid);
    if (Math.abs(x - clamped) < 1e-9) break;
    if (x < clamped) low = mid;
    else high = mid;
  }
  return bezierAxis(points.y1, points.y2, mid);
}

/// The value a channel holds at a frame, or `undefined` for an empty channel.
///
/// Held flat outside the keyed range rather than extrapolated, matching the
/// Rust: extrapolation invents motion the author never keyed.
export function evaluateChannel(channel: ChannelKeys, frame: number): number | undefined {
  const keys = channel.keys;
  if (keys.length === 0) return undefined;
  const first = keys[0]!;
  const last = keys[keys.length - 1]!;
  if (frame <= Number(first.frame)) return first.value;
  if (frame >= Number(last.frame)) return last.value;

  // Binary search for the segment; a per-frame evaluator cannot be linear in
  // key count.
  let low = 0;
  let high = keys.length;
  while (low < high) {
    const mid = (low + high) >>> 1;
    if (Number(keys[mid]!.frame) <= frame) low = mid + 1;
    else high = mid;
  }
  const from = keys[low - 1]!;
  const to = keys[low]!;
  const span = Number(to.frame) - Number(from.frame);
  if (span === 0) return from.value;

  const t = (frame - Number(from.frame)) / span;
  return from.value + (to.value - from.value) * easeAt(from.easing, from.bezier, t);
}

/// The channel's value range across its keys, for scaling the speed graph.
///
/// Includes overshoot: an easing whose y leaves 0–1 carries the value past its
/// neighbouring keys, and a graph that clipped it would hide the very thing an
/// author opened the curve editor to see.
export function channelValueRange(
  channel: ChannelKeys,
  samplesPerSegment = 8,
): { readonly min: number; readonly max: number } {
  if (channel.keys.length === 0) return { min: 0, max: 1 };
  let min = Number.POSITIVE_INFINITY;
  let max = Number.NEGATIVE_INFINITY;
  const consider = (value: number): void => {
    if (value < min) min = value;
    if (value > max) max = value;
  };
  for (let index = 0; index < channel.keys.length; index += 1) {
    const key = channel.keys[index]!;
    consider(key.value);
    const next = channel.keys[index + 1];
    if (!next) continue;
    for (let step = 1; step < samplesPerSegment; step += 1) {
      const t = step / samplesPerSegment;
      const eased = easeAt(key.easing, key.bezier, t);
      consider(key.value + (next.value - key.value) * eased);
    }
  }
  if (min === max) {
    // A flat channel still needs a band to draw in.
    return { min: min - 0.5, max: max + 0.5 };
  }
  return { min, max };
}
